-- PT122-S4-Q22. Batch 13.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT122-S4-Q22$batch13$ AND q.stimulus=$batch13$Economist: Some people argue that when large countries split into several small countries, the world economy is harmed by increased barriers to free trade in the form of an increased number of national tariffs. But small countries do not think of themselves as economically self-sufficient. Therefore, such division of large countries does not increase barriers to free trade.$batch13$ AND q.prompt=$batch13$Which one of the following, if assumed, enables the economist's conclusion to be properly drawn?$batch13$ AND q.correct_choice=$batch13$C$batch13$) THEN RAISE EXCEPTION 'Question changed: PT122-S4-Q22'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch13$PT122-S4-Q22$batch13$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT122-S4-Q22'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT122-S4-Q22$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Opposing Point$batch13$, $batch13$Some say splitting large countries harms the world economy by adding national tariffs.$batch13$), (1, $batch13$Conclusion$batch13$, $batch13$Splitting large countries does not increase barriers to free trade.$batch13$), (2, $batch13$Evidence$batch13$, $batch13$Small countries don't think of themselves as economically self-sufficient.$batch13$), (3, $batch13$Evaluate$batch13$, $batch13$The evidence is about how small countries see themselves. The conclusion is about trade barriers. They connect only if trade barriers come from countries that think they're self-sufficient.$batch13$), (4, $batch13$Goal$batch13$, $batch13$Only countries that see themselves as self-sufficient impose trade barriers.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT122-S4-Q22$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$A right to split says nothing about whether splitting raises trade barriers.$batch13$), ($batch13$B$batch13$, $batch13$A stronger world economy doesn't show trade barriers stay the same.$batch13$), ($batch13$C$batch13$, $batch13$Imposing barriers requires seeing yourself as self-sufficient. Small countries don't, so they won't impose barriers.$batch13$), ($batch13$D$batch13$, $batch13$Barriers being harmful doesn't show that splitting countries won't create them.$batch13$), ($batch13$E$batch13$, $batch13$Comparing large and small countries' self-sufficiency still doesn't connect self-sufficiency to tariffs.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT122-S4-Q22$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
